-- ============================================================
--  DDC website — seed/update legal page content
--  Run AFTER legal_schema.sql. Re-running UPDATES the content.
-- ============================================================

insert into public.legal_pages (slug, title, body) values ('privacy', '{"de": "Datenschutzerklärung", "en": "Privacy Policy"}'::jsonb, '{"de": "## 1. Verantwortlicher\n\nVerantwortlich für die Verarbeitung personenbezogener Daten auf dieser Website im Sinne der Datenschutz-Grundverordnung (DSGVO) ist:\n\n**DDC – FJ Donner**\nVon-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland\nE-Mail: fj-donner@projecttechnic.de\nTelefon: +49 175 59 41 367\n\n## 2. Überblick\n\nDer Schutz Ihrer personenbezogenen Daten ist uns wichtig. Diese Datenschutzerklärung informiert Sie darüber, welche Daten wir erheben, zu welchen Zwecken wir sie verarbeiten, auf welcher Rechtsgrundlage dies geschieht, an wen wir Daten weitergeben und welche Rechte Ihnen zustehen. Sie gilt für diese Website sowie für den zugehörigen Administrationsbereich.\n\n## 3. Welche Daten wir verarbeiten\n\n### 3.1 Kontaktformular\n\nWenn Sie uns über das Kontaktformular eine Nachricht senden, verarbeiten wir die von Ihnen angegebenen Daten: **Name, E-Mail-Adresse, Unternehmen (optional) und den Inhalt Ihrer Nachricht** sowie den Zeitpunkt der Übermittlung. Diese Daten verwenden wir ausschließlich zur Bearbeitung Ihrer Anfrage und für eventuelle Anschlussfragen.\n\n### 3.2 Anmeldung über Google (nur für Administratoren)\n\nDer Zugang zum Administrationsbereich dieser Website kann über **Google OAuth** erfolgen. Meldet sich eine berechtigte Person über Google an, erhalten wir von Google grundlegende Profilinformationen – insbesondere **Name, E-Mail-Adresse und ggf. das Profilbild**. Wir nutzen diese Informationen ausschließlich, um zu prüfen, ob die anmeldende Person auf unserer Liste berechtigter Administratoren steht, und um die Anmeldesitzung zu verwalten. Wir fordern keine weitergehenden Zugriffsrechte auf Ihr Google-Konto an.\n\n### 3.3 Server-Logdateien\n\nBeim Aufruf der Website werden durch den Hosting-Anbieter automatisch technische Zugriffsdaten verarbeitet (z. B. IP-Adresse, Datum und Uhrzeit, aufgerufene Seite, Browsertyp). Diese Daten sind zur Bereitstellung und Sicherheit der Website erforderlich.\n\n### 3.4 Cookies\n\nWir setzen ein technisch notwendiges **Sitzungs-Cookie** ein, das ausschließlich der Anmeldung im Administrationsbereich dient. Es enthält keine Werbekennungen und wird nach dem Abmelden bzw. nach Ablauf der Sitzung ungültig. Für den normalen Besuch der Website ist keine Zustimmung zu nicht notwendigen Cookies erforderlich, da wir keine solchen einsetzen.\n\n## 4. Zwecke und Rechtsgrundlagen\n\nWir verarbeiten personenbezogene Daten auf folgenden Rechtsgrundlagen der DSGVO:\n\n- **Art. 6 Abs. 1 lit. b DSGVO** – zur Bearbeitung von Anfragen und zur Verwaltung von Administratorzugängen;\n- **Art. 6 Abs. 1 lit. f DSGVO** – aufgrund unseres berechtigten Interesses am sicheren, störungsfreien Betrieb der Website;\n- **Art. 6 Abs. 1 lit. c DSGVO** – soweit wir zur Verarbeitung gesetzlich verpflichtet sind.\n\n## 5. Nutzung von Google-Nutzerdaten (Google API Services User Data Policy)\n\nUnsere Verwendung von Informationen, die über Google-APIs empfangen werden, erfolgt in Übereinstimmung mit der **Google API Services User Data Policy**, einschließlich der **Limited-Use-Anforderungen**. Konkret bedeutet dies:\n\n- Wir verwenden die über Google erhaltenen Daten **ausschließlich** zur Authentifizierung und Autorisierung berechtigter Administratoren.\n- Wir geben diese Daten **nicht** an Dritte weiter, außer soweit dies zur Bereitstellung des Dienstes erforderlich, gesetzlich vorgeschrieben oder von Ihnen ausdrücklich gewünscht ist.\n- Wir nutzen diese Daten **nicht** für Werbezwecke.\n- Wir verwenden **keine** menschliche Auswertung der Daten, außer mit Ihrer ausdrücklichen Einwilligung, zu Sicherheitszwecken, zur Einhaltung geltenden Rechts oder wenn die Daten aggregiert und anonymisiert sind.\n\n## 6. Empfänger und Auftragsverarbeiter\n\nZur Bereitstellung der Website setzen wir sorgfältig ausgewählte Dienstleister ein, die Daten in unserem Auftrag verarbeiten:\n\n- **Supabase** – Hosting der Datenbank (Inhalte und Kontaktnachrichten).\n- **Google LLC** – Bereitstellung der Anmeldung über Google OAuth.\n- Unser jeweiliger **Hosting-Anbieter** – Betrieb des Servers und Auslieferung der Website.\n\nMit diesen Dienstleistern bestehen, soweit erforderlich, Verträge zur Auftragsverarbeitung.\n\n## 7. Datenübermittlung in Drittländer\n\nEinige der genannten Dienstleister können Daten außerhalb der Europäischen Union (z. B. in den USA) verarbeiten. In diesen Fällen wird ein angemessenes Datenschutzniveau durch geeignete Garantien, insbesondere **Standardvertragsklauseln der EU-Kommission**, sichergestellt.\n\n## 8. Speicherdauer\n\nWir speichern personenbezogene Daten nur so lange, wie es für die jeweiligen Zwecke erforderlich ist oder gesetzliche Aufbewahrungsfristen dies vorschreiben. Kontaktnachrichten werden gelöscht, sobald die Bearbeitung abgeschlossen ist und keine gesetzlichen Pflichten entgegenstehen.\n\n## 9. Ihre Rechte\n\nIhnen stehen nach der DSGVO folgende Rechte zu: **Auskunft** (Art. 15), **Berichtigung** (Art. 16), **Löschung** (Art. 17), **Einschränkung der Verarbeitung** (Art. 18), **Datenübertragbarkeit** (Art. 20) sowie **Widerspruch** (Art. 21). Zudem haben Sie das Recht, sich bei einer Datenschutz-Aufsichtsbehörde zu beschweren.\n\nUm Ihre Rechte auszuüben oder die **Löschung Ihrer Daten** zu verlangen, kontaktieren Sie uns unter **fj-donner@projecttechnic.de**.\n\n## 10. Datensicherheit\n\nWir treffen technische und organisatorische Maßnahmen, um Ihre Daten gegen unbefugten Zugriff, Verlust oder Manipulation zu schützen. Die Datenübertragung erfolgt verschlüsselt über HTTPS.\n\n## 11. Minderjährige\n\nDiese Website richtet sich nicht an Kinder. Wir erheben nicht wissentlich personenbezogene Daten von Personen unter 16 Jahren.\n\n## 12. Änderungen dieser Datenschutzerklärung\n\nWir behalten uns vor, diese Datenschutzerklärung anzupassen, um sie an geänderte Rechtslagen oder Änderungen unserer Leistungen anzupassen. Es gilt die jeweils auf dieser Seite veröffentlichte Fassung.\n\n## 13. Kontakt\n\nBei Fragen zum Datenschutz oder zur Ausübung Ihrer Rechte erreichen Sie uns unter:\n**DDC – FJ Donner**, Von-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland, E-Mail: fj-donner@projecttechnic.de.\n", "en": "## 1. Data Controller\n\nThe party responsible for processing personal data on this website within the meaning of the General Data Protection Regulation (GDPR) is:\n\n**DDC – FJ Donner**\nVon-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland\nEmail: fj-donner@projecttechnic.de\nPhone: +49 175 59 41 367\n\n## 2. Overview\n\nProtecting your personal data is important to us. This Privacy Policy explains what data we collect, the purposes and legal bases for processing it, with whom we share it, and the rights available to you. It applies to this website and its associated administration area.\n\n## 3. What Data We Process\n\n### 3.1 Contact Form\n\nWhen you send us a message through the contact form, we process the data you provide: **name, email address, company (optional) and the content of your message**, together with the time of submission. We use this data solely to handle your enquiry and any follow-up.\n\n### 3.2 Sign-in with Google (administrators only)\n\nAccess to the administration area may be granted via **Google OAuth**. When an authorized person signs in with Google, we receive basic profile information from Google — in particular **name, email address and, where available, profile picture**. We use this information solely to verify that the person is on our list of authorized administrators and to manage the login session. We do not request any broader access to your Google account.\n\n### 3.3 Server Log Files\n\nWhen the website is accessed, the hosting provider automatically processes technical access data (e.g. IP address, date and time, page requested, browser type). This data is necessary to provide and secure the website.\n\n### 3.4 Cookies\n\nWe use a strictly necessary **session cookie** that serves only to keep you signed in to the administration area. It contains no advertising identifiers and expires when you log out or the session ends. Ordinary browsing of the website requires no consent to non-essential cookies, as we do not use any.\n\n## 4. Purposes and Legal Bases\n\nWe process personal data on the following GDPR legal bases:\n\n- **Art. 6(1)(b) GDPR** – to handle enquiries and manage administrator access;\n- **Art. 6(1)(f) GDPR** – our legitimate interest in the secure, uninterrupted operation of the website;\n- **Art. 6(1)(c) GDPR** – where processing is required by law.\n\n## 5. Use of Google User Data (Google API Services User Data Policy)\n\nOur use of information received from Google APIs adheres to the **Google API Services User Data Policy**, including the **Limited Use requirements**. Specifically:\n\n- We use the data received via Google **solely** to authenticate and authorize eligible administrators.\n- We **do not** transfer this data to third parties except as necessary to provide the service, as required by law, or as expressly requested by you.\n- We **do not** use this data for advertising.\n- We **do not** allow humans to read the data, except with your explicit consent, for security purposes, to comply with applicable law, or where the data is aggregated and anonymized.\n\n## 6. Recipients and Processors\n\nTo operate the website we use carefully selected service providers that process data on our behalf:\n\n- **Supabase** – database hosting (content and contact messages).\n- **Google LLC** – provision of sign-in via Google OAuth.\n- Our **hosting provider** – operating the server and delivering the website.\n\nWhere required, data processing agreements are in place with these providers.\n\n## 7. International Transfers\n\nSome of the providers above may process data outside the European Union (e.g. in the USA). In such cases an adequate level of protection is ensured through appropriate safeguards, in particular the **EU Commission''s Standard Contractual Clauses**.\n\n## 8. Retention\n\nWe store personal data only for as long as necessary for the relevant purposes or as required by statutory retention periods. Contact messages are deleted once your enquiry has been handled and no legal obligations require retention.\n\n## 9. Your Rights\n\nUnder the GDPR you have the rights to **access** (Art. 15), **rectification** (Art. 16), **erasure** (Art. 17), **restriction** (Art. 18), **data portability** (Art. 20) and **objection** (Art. 21). You also have the right to lodge a complaint with a data protection supervisory authority.\n\nTo exercise your rights or to request **deletion of your data**, contact us at **fj-donner@projecttechnic.de**.\n\n## 10. Data Security\n\nWe implement technical and organizational measures to protect your data against unauthorized access, loss or manipulation. Data is transmitted encrypted via HTTPS.\n\n## 11. Children\n\nThis website is not directed at children. We do not knowingly collect personal data from anyone under the age of 16.\n\n## 12. Changes to This Policy\n\nWe may update this Privacy Policy to reflect changes in the law or in our services. The version published on this page at any given time applies.\n\n## 13. Contact\n\nFor any privacy questions or to exercise your rights, contact:\n**DDC – FJ Donner**, Von-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland, email: fj-donner@projecttechnic.de.\n"}'::jsonb)
  on conflict (slug) do update set title = excluded.title, body = excluded.body, updated_at = now();

insert into public.legal_pages (slug, title, body) values ('terms', '{"de": "Nutzungsbedingungen", "en": "Terms of Service"}'::jsonb, '{"de": "## 1. Geltungsbereich und Vertragspartner\n\nDiese Nutzungsbedingungen regeln die Nutzung der Website und des Administrationsbereichs von:\n\n**DDC – FJ Donner**\nVon-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland\nE-Mail: fj-donner@projecttechnic.de\n\nMit dem Zugriff auf die Website und deren Nutzung erklären Sie sich mit diesen Bedingungen einverstanden. Wenn Sie nicht einverstanden sind, nutzen Sie die Website bitte nicht.\n\n## 2. Leistungsbeschreibung\n\nDie Website informiert über unsere Leistungen in den Bereichen Produktentwicklung und Engineering und bietet ein Kontaktformular zur Kontaktaufnahme. Der Administrationsbereich dient ausschließlich der Verwaltung der Website-Inhalte durch berechtigte Personen.\n\n## 3. Zugang zum Administrationsbereich\n\nDer Zugang zum Administrationsbereich ist ausschließlich berechtigten Personen vorbehalten und kann per Passwort oder über die Anmeldung mit Google erfolgen. Sie sind verpflichtet, Zugangsdaten vertraulich zu behandeln und vor dem Zugriff Dritter zu schützen. Wir sind berechtigt, Zugänge zu sperren, wenn ein Missbrauch vorliegt oder zu befürchten ist.\n\n## 4. Zulässige Nutzung\n\nSie verpflichten sich, die Website nicht missbräuchlich zu nutzen, insbesondere nicht:\n\n- gegen geltendes Recht zu verstoßen;\n- Schadsoftware zu verbreiten oder die Sicherheit oder Verfügbarkeit der Website zu beeinträchtigen;\n- unbefugt auf Systeme, Daten oder Konten zuzugreifen;\n- rechtswidrige, beleidigende oder irreführende Inhalte über das Kontaktformular zu übermitteln.\n\n## 5. Inhalte und Rechte\n\nAlle Inhalte dieser Website – insbesondere Texte, Grafiken, das Logo und die Gestaltung – sind urheberrechtlich geschützt und stehen im Eigentum von DDC – FJ Donner oder der jeweiligen Rechteinhaber. Eine Nutzung außerhalb der gesetzlich zulässigen Grenzen bedarf unserer vorherigen schriftlichen Zustimmung.\n\n## 6. Von Ihnen übermittelte Inhalte\n\nFür Inhalte, die Sie über das Kontaktformular übermitteln, sind Sie selbst verantwortlich. Sie sichern zu, dass Sie zur Übermittlung berechtigt sind und keine Rechte Dritter verletzen.\n\n## 7. Dienste Dritter\n\nDie Website nutzt Dienste Dritter (u. a. Google für die Anmeldung sowie Supabase für die Datenspeicherung). Für diese Dienste gelten zusätzlich die jeweiligen Bedingungen und Datenschutzhinweise der Anbieter.\n\n## 8. Gewährleistung und Verfügbarkeit\n\nWir bemühen uns um einen zuverlässigen Betrieb der Website, können jedoch keine ununterbrochene Verfügbarkeit oder Fehlerfreiheit garantieren. Die Website wird „wie besehen\" bereitgestellt.\n\n## 9. Haftungsbeschränkung\n\nWir haften unbeschränkt bei Vorsatz und grober Fahrlässigkeit sowie bei der Verletzung von Leben, Körper oder Gesundheit. Bei einfacher Fahrlässigkeit haften wir nur bei Verletzung einer wesentlichen Vertragspflicht und der Höhe nach begrenzt auf den vorhersehbaren, vertragstypischen Schaden. Im Übrigen ist die Haftung ausgeschlossen, soweit gesetzlich zulässig.\n\n## 10. Freistellung\n\nSie stellen uns von Ansprüchen Dritter frei, die aus einer rechtswidrigen Nutzung der Website durch Sie oder aus einem Verstoß gegen diese Bedingungen resultieren.\n\n## 11. Beendigung\n\nWir sind berechtigt, den Zugang zum Administrationsbereich jederzeit zu sperren oder zu beenden, insbesondere bei Verstößen gegen diese Bedingungen.\n\n## 12. Anwendbares Recht und Gerichtsstand\n\nEs gilt das Recht der Bundesrepublik Deutschland unter Ausschluss des UN-Kaufrechts. Soweit gesetzlich zulässig, ist Gerichtsstand der Sitz von DDC – FJ Donner.\n\n## 13. Änderungen der Bedingungen\n\nWir behalten uns vor, diese Nutzungsbedingungen anzupassen. Es gilt die jeweils auf dieser Seite veröffentlichte Fassung.\n\n## 14. Kontakt\n\n**DDC – FJ Donner**, Von-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland, E-Mail: fj-donner@projecttechnic.de.\n", "en": "## 1. Scope and Contracting Party\n\nThese Terms of Service govern your use of the website and administration area of:\n\n**DDC – FJ Donner**\nVon-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland\nEmail: fj-donner@projecttechnic.de\n\nBy accessing and using the website you agree to these Terms. If you do not agree, please do not use the website.\n\n## 2. Description of Service\n\nThe website provides information about our product development and engineering services and offers a contact form for enquiries. The administration area is intended solely for the management of website content by authorized persons.\n\n## 3. Access to the Administration Area\n\nAccess to the administration area is reserved for authorized persons and may be granted by password or via sign-in with Google. You must keep credentials confidential and protect them from third-party access. We may suspend access where misuse occurs or is reasonably suspected.\n\n## 4. Acceptable Use\n\nYou agree not to misuse the website, and in particular not to:\n\n- violate applicable law;\n- distribute malware or impair the security or availability of the website;\n- gain unauthorized access to systems, data or accounts;\n- submit unlawful, offensive or misleading content through the contact form.\n\n## 5. Content and Intellectual Property\n\nAll content on this website — in particular text, graphics, the logo and the design — is protected by copyright and owned by DDC – FJ Donner or the respective rights holders. Any use beyond what is permitted by law requires our prior written consent.\n\n## 6. Content You Submit\n\nYou are responsible for content you submit through the contact form. You represent that you are entitled to submit it and that it does not infringe the rights of third parties.\n\n## 7. Third-Party Services\n\nThe website uses third-party services (including Google for sign-in and Supabase for data storage). The respective terms and privacy notices of those providers additionally apply.\n\n## 8. Warranty and Availability\n\nWe strive to operate the website reliably but cannot guarantee uninterrupted availability or freedom from errors. The website is provided \"as is\".\n\n## 9. Limitation of Liability\n\nWe are liable without limitation for intent and gross negligence and for injury to life, body or health. For slight negligence we are liable only for breach of a material contractual obligation and limited to the foreseeable, contract-typical damage. Otherwise liability is excluded to the extent permitted by law.\n\n## 10. Indemnification\n\nYou will indemnify us against third-party claims arising from your unlawful use of the website or from your breach of these Terms.\n\n## 11. Termination\n\nWe may suspend or terminate access to the administration area at any time, in particular in the event of breaches of these Terms.\n\n## 12. Governing Law and Jurisdiction\n\nThe law of the Federal Republic of Germany applies, excluding the UN Convention on Contracts for the International Sale of Goods. To the extent permitted by law, the place of jurisdiction is the registered seat of DDC – FJ Donner.\n\n## 13. Changes to These Terms\n\nWe may amend these Terms of Service. The version published on this page at any given time applies.\n\n## 14. Contact\n\n**DDC – FJ Donner**, Von-Bodelschwingh-Str. 14, 33175 Bad Lippspringe, Deutschland, email: fj-donner@projecttechnic.de.\n"}'::jsonb)
  on conflict (slug) do update set title = excluded.title, body = excluded.body, updated_at = now();

